/**
 * Jointly moves selected pairs of parallel edges.
 * Candidate pair positions are generated from nearby fish coordinates,
 * evaluated with KD-tree strip deltas, and exactly rescored only when their
 * estimated gain is competitive. This allows coordinated corridor expansion
 * or contraction that cannot be reached through strictly improving
 * single-edge moves.
 */
void paired_parallel_edge_sweep(SAState& state) {
    const double deadline = std::max(0.20, ACTUAL_TIME_LIMIT_SECONDS - 0.03);
    const int MAX_PAIRS = 180;
    const int SIDE_LIMIT = 11; // At most 23 coordinates per edge.

    if (state.poly.size() < 4 || global_timer.elapsed() >= deadline) return;

    struct EdgePair {
        int first, second, priority;
    };

    const int m = (int)state.poly.size();
    std::vector<EdgePair> pairs;
    pairs.reserve(m * m / 2);

    for (int i = 0; i < m; ++i) {
        const Point& a = state.poly[i];
        const Point& b = state.poly[(i + 1) % m];
        const bool vertical = (a.x == b.x);
        const int span_a = vertical ? std::abs(a.y - b.y)
                                    : std::abs(a.x - b.x);

        for (int j = i + 2; j < m; ++j) {
            if (i == 0 && j == m - 1) continue;

            const Point& c = state.poly[j];
            const Point& d = state.poly[(j + 1) % m];
            if ((c.x == d.x) != vertical) continue;

            const int span_b = vertical ? std::abs(c.y - d.y)
                                        : std::abs(c.x - d.x);
            pairs.push_back({i, j, span_a + span_b});
        }
    }

    std::sort(pairs.begin(), pairs.end(),
              [](const EdgePair& lhs, const EdgePair& rhs) {
                  return lhs.priority > rhs.priority;
              });
    if ((int)pairs.size() > MAX_PAIRS) pairs.resize(MAX_PAIRS);

    auto nearby_coordinates =
        [&](const std::vector<int>& guides, int value) {
            std::vector<int> result;
            result.reserve(2 * SIDE_LIMIT + 1);
            result.push_back(value);

            auto it = std::lower_bound(guides.begin(), guides.end(), value);
            int left = (int)(it - guides.begin()) - 1;
            int right = (int)(it - guides.begin());
            int left_used = 0;
            int right_used = 0;

            while ((left >= 0 && left_used < SIDE_LIMIT) ||
                   (right < (int)guides.size() && right_used < SIDE_LIMIT)) {
                if (left >= 0 && left_used < SIDE_LIMIT &&
                    (right >= (int)guides.size() ||
                     value - guides[left] <= guides[right] - value)) {
                    result.push_back(guides[left--]);
                    ++left_used;
                } else if (right < (int)guides.size() &&
                           right_used < SIDE_LIMIT) {
                    result.push_back(guides[right++]);
                    ++right_used;
                } else {
                    break;
                }
            }

            std::sort(result.begin(), result.end());
            result.erase(std::unique(result.begin(), result.end()), result.end());
            return result;
        };

    auto strip_delta = [&](bool vertical, int old_coord, int new_coord,
                           Point p1, Point p2, int& dm, int& ds) {
        int min_x, max_x, min_y, max_y;
        if (vertical) {
            min_x = std::min(old_coord, new_coord);
            max_x = std::max(old_coord, new_coord);
            min_y = std::min(p1.y, p2.y);
            max_y = std::max(p1.y, p2.y);
        } else {
            min_x = std::min(p1.x, p2.x);
            max_x = std::max(p1.x, p2.x);
            min_y = std::min(old_coord, new_coord);
            max_y = std::max(old_coord, new_coord);
        }

        if (min_x > max_x || min_y > max_y) {
            dm = ds = 0;
            return;
        }

        calculate_score_delta_for_rectangle(
            min_x, max_x, min_y, max_y, dm, ds);

        if (vertical && new_coord > old_coord && min_x == old_coord)
            calculate_score_delta_for_rectangle(
                old_coord, old_coord, min_y, max_y, dm, ds);
        if (!vertical && new_coord > old_coord && min_y == old_coord)
            calculate_score_delta_for_rectangle(
                min_x, max_x, old_coord, old_coord, dm, ds);
    };

    bool improved = true;
    while (improved && global_timer.elapsed() < deadline) {
        improved = false;
        long long best_gain = 0;
        std::vector<Point> best_poly;
        int best_m = state.m_count;
        int best_s = state.s_count;

        for (const EdgePair& pair : pairs) {
            if (global_timer.elapsed() >= deadline) break;

            const int e1 = pair.first;
            const int e2 = pair.second;
            const Point p1 = state.poly[e1];
            const Point p2 = state.poly[(e1 + 1) % m];
            const Point q1 = state.poly[e2];
            const Point q2 = state.poly[(e2 + 1) % m];

            const bool vertical = (p1.x == p2.x);
            const int old1 = vertical ? p1.x : p1.y;
            const int old2 = vertical ? q1.x : q1.y;
            const std::vector<int>& guides =
                vertical ? static_x_guides : static_y_guides;

            if (guides.empty()) continue;

            const std::vector<int> c1s = nearby_coordinates(guides, old1);
            const std::vector<int> c2s = nearby_coordinates(guides, old2);

            for (int c1 : c1s) {
                if (global_timer.elapsed() >= deadline) break;

                for (int c2 : c2s) {
                    if (global_timer.elapsed() >= deadline) break;
                    if (c1 == old1 && c2 == old2) continue;
                    if (c1 == c2) continue;

                    int d1m, d1s, d2m, d2s;
                    strip_delta(vertical, old1, c1, p1, p2, d1m, d1s);
                    strip_delta(vertical, old2, c2, q1, q2, d2m, d2s);

                    const long long rough_gain =
                        (long long)d1m - d1s + d2m - d2s;
                    if (rough_gain <= best_gain) continue;

                    std::vector<Point> candidate = state.poly;
                    if (vertical) {
                        candidate[e1].x = c1;
                        candidate[(e1 + 1) % m].x = c1;
                        candidate[e2].x = c2;
                        candidate[(e2 + 1) % m].x = c2;
                    } else {
                        candidate[e1].y = c1;
                        candidate[(e1 + 1) % m].y = c1;
                        candidate[e2].y = c2;
                        candidate[(e2 + 1) % m].y = c2;
                    }

                    if (!is_polygon_structurally_sound(candidate) ||
                        !has_distinct_vertices_unordered(candidate)) {
                        continue;
                    }

                    std::vector<int> critical_edges = {
                        (e1 - 1 + m) % m, e1, (e1 + 1) % m,
                        (e2 - 1 + m) % m, e2, (e2 + 1) % m
                    };
                    if (has_self_intersection_locally(
                            candidate, critical_edges)) {
                        continue;
                    }

                    int candidate_m = 0;
                    int candidate_s = 0;
                    calculate_score_from_scratch(
                        candidate, candidate_m, candidate_s);

                    const long long exact_gain =
                        (long long)candidate_m - candidate_s -
                        ((long long)state.m_count - state.s_count);

                    if (exact_gain > best_gain) {
                        best_gain = exact_gain;
                        best_poly = std::move(candidate);
                        best_m = candidate_m;
                        best_s = candidate_s;
                    }
                }
            }
        }

        if (best_gain > 0) {
            state.poly = std::move(best_poly);
            state.m_count = best_m;
            state.s_count = best_s;
            improved = true;
        }
    }
}

